  "c504700154.lua":"--大神官デ・ザード\nlocal s,id=GetID()\nfunction s.initial_effect(c)\n\t--check\n\tlocal e1=Effect.CreateEffect(c)\n\te1:SetType(EFFECT_TYPE_SINGLE+EFFECT_TYPE_CONTINUOUS)\n\te1:SetCode(EVENT_BATTLE_DESTROYING)\n\te1:SetOperation(s.regop)\n\tc:RegisterEffect(e1)\n\t--negate\n\tlocal e2=Effect.CreateEffect(c)\n\te2:SetCategory(CATEGORY_DESTROY+CATEGORY_NEGATE)\n\te2:SetType(EFFECT_TYPE_QUICK_F)\n\te2:SetCode(EVENT_CHAINING)\n\te2:SetRange(LOCATION_MZONE)\n\te2:SetProperty(EFFECT_FLAG_DAMAGE_STEP+EFFECT_FLAG_DAMAGE_CAL)\n\te2:SetCondition(s.discon)\n\te2:SetTarget(s.distg)\n\te2:SetOperation(s.disop)\n\tc:RegisterEffect(e2)\n\t--special summon\n\tlocal e3=Effect.CreateEffect(c)\n\te3:SetDescription(aux.Stringid(id,0))\n\te3:SetCategory(CATEGORY_SPECIAL_SUMMON)\n\te3:SetType(EFFECT_TYPE_IGNITION)\n\te3:SetRange(LOCATION_MZONE)\n\te3:SetCondition(s.spcon)\n\te3:SetCost(s.spcost)\n\te3:SetTarget(s.sptg)\n\te3:SetOperation(s.spop)\n\tc:RegisterEffect(e3)\n\t--Double Snare\n\tlocal e4=Effect.CreateEffect(c)\n\te4:SetType(EFFECT_TYPE_SINGLE)\n\te4:SetProperty(EFFECT_FLAG_CANNOT_DISABLE+EFFECT_FLAG_UNCOPYABLE+EFFECT_FLAG_SINGLE_RANGE)\n\te4:SetRange(LOCATION_MZONE)\n\te4:SetCondition(s.effcon)\n\te4:SetCode(3682106)\n\tc:RegisterEffect(e4)\nend\ns.listed_names={39711336}\nfunction s.effcon(e,tp,eg,ep,ev,re,r,rp)\n\treturn e:GetHandler():GetFlagEffect(id+1)>0\nend\nfunction s.regop(e,tp,eg,ep,ev,re,r,rp)\n\tlocal c=e:GetHandler()\n\tif c:IsRelateToBattle() then\n\t\tc:RegisterFlagEffect(id+1,RESET_EVENT+RESETS_STANDARD,0,0)\n\tend\nend\nfunction s.discon(e,tp,eg,ep,ev,re,r,rp)\n\tif e:GetHandler():GetFlagEffect(id+1)==0 or not re:IsHasProperty(EFFECT_FLAG_CARD_TARGET) then return false end\n\tlocal tg=Duel.GetChainInfo(ev,CHAININFO_TARGET_CARDS)\n\tif not tg or not tg:IsContains(e:GetHandler()) then return false end\n\treturn re:IsHasType(EFFECT_TYPE_ACTIVATE)\nend\nfunction s.distg(e,tp,eg,ep,ev,re,r,rp,chk)\n\tif chk==0 then return true end\n\tDuel.SetOperationInfo(0,CATEGORY_NEGATE,eg,1,0,0)\n\tif re:GetHandler():IsRelateToEffect(re) then\n\t\tDuel.SetOperationInfo(0,CATEGORY_DESTROY,eg,1,0,0)\n\tend\nend\nfunction s.disop(e,tp,eg,ep,ev,re,r,rp)\n\tif Duel.GetCurrentChain()~=ev+1 then return end\n\tif Duel.NegateActivation(ev) and re:GetHandler():IsRelateToEffect(re) then\n\t\tDuel.Destroy(eg,REASON_EFFECT)\n\tend\nend\nfunction s.spcon(e,tp,eg,ep,ev,re,r,rp)\n\treturn e:GetHandler():GetFlagEffect(id+1)>=2\nend\nfunction s.spcost(e,tp,eg,ep,ev,re,r,rp,chk)\n\tif chk==0 then return e:GetHandler():IsReleasable() end\n\tDuel.Release(e:GetHandler(),REASON_COST)\nend\nfunction s.filter(c,e,tp)\n\treturn c:IsCode(39711336) and c:IsCanBeSpecialSummoned(e,0,tp,true,false)\nend\nfunction s.sptg(e,tp,eg,ep,ev,re,r,rp,chk)\n\tlocal ft=Duel.GetLocationCount(tp,LOCATION_MZONE)\n\tif e:GetHandler():GetSequence()<5 then ft=ft+1 end\n\tif chk==0 then return ft>0 end\n\tDuel.SetOperationInfo(0,CATEGORY_SPECIAL_SUMMON,nil,0,tp,LOCATION_DECK+LOCATION_HAND)\nend\nfunction s.spop(e,tp,eg,ep,ev,re,r,rp)\n\tif Duel.GetLocationCount(tp,LOCATION_MZONE)<=0 then return end\n\tDuel.Hint(HINT_SELECTMSG,tp,HINTMSG_SPSUMMON)\n\tlocal g=Duel.SelectMatchingCard(tp,s.filter,tp,LOCATION_DECK+LOCATION_HAND,0,1,1,nil,e,tp)\n\tif #g>0 then\n\t\tif Duel.SpecialSummon(g,0,tp,tp,true,false,POS_FACEUP)>0 then\n\t\t\tg:GetFirst():CompleteProcedure()\n\t\tend\n\telse\n\t\tDuel.GoatConfirm(tp,LOCATION_HAND+LOCATION_DECK)\n\tend\nend\n",
  "goat/c504700155.lua":"--深淵の指名者\n--Abyssal Designator (GOAT)\nlocal s,id=GetID()\nfunction s.initial_effect(c)\n\t--Activate\n\tlocal e1=Effect.CreateEffect(c)\n\te1:SetType(EFFECT_TYPE_ACTIVATE)\n\te1:SetCode(EVENT_FREE_CHAIN)\n\te1:SetProperty(EFFECT_FLAG_PLAYER_TARGET)\n\te1:SetCost(s.cost)\n\te1:SetTarget(s.target)\n\te1:SetOperation(s.activate)\n\tc:RegisterEffect(e1)\nend\nfunction s.cost(e,tp,eg,ep,ev,re,r,rp,chk)\n\tif chk==0 then return Duel.CheckLPCost(tp,1000) end\n\tDuel.PayLPCost(tp,1000)\nend\nfunction s.target(e,tp,eg,ep,ev,re,r,rp,chk)\n\tif chk==0 then return true end\n\tDuel.Hint(HINT_SELECTMSG,tp,HINTMSG_ATTRIBUTE)\n\tlocal att=Duel.AnnounceAttribute(tp,1,ATTRIBUTE_ALL)\n\tDuel.Hint(HINT_SELECTMSG,tp,HINTMSG_RACE)\n\tlocal rc=Duel.AnnounceRace(tp,1,RACE_ALL)\n\te:SetLabel(att)\n\tDuel.SetTargetPlayer(1-tp)\n\tDuel.SetTargetParam(rc)\n\tDuel.SetOperationInfo(0,CATEGORY_TOGRAVE,nil,1,1-tp,LOCATION_HAND+LOCATION_DECK)\nend\nfunction s.filter(c,rc,att)\n\treturn c:IsRace(rc) and c:IsAttribute(att) and c:IsAbleToGrave()\nend\nfunction s.activate(e,tp,eg,ep,ev,re,r,rp)\n\tlocal att=e:GetLabel()\n\tlocal p,rc=Duel.GetChainInfo(0,CHAININFO_TARGET_PLAYER,CHAININFO_TARGET_PARAM)\n\tDuel.Hint(HINT_SELECTMSG,tp,HINTMSG_TOGRAVE)\n\tlocal g=Duel.SelectMatchingCard(p,s.filter,p,LOCATION_HAND+LOCATION_DECK,0,1,1,nil,rc,att)\n\tif #g>0 then\n\t\tDuel.SendtoGrave(g,REASON_EFFECT)\n\telse\n\t\tDuel.GoatConfirm(tp,LOCATION_HAND+LOCATION_DECK)\n\tend\nend\n",
